// Router for kolaboro.com feature modules. Each kbx_<x>.js exports PATHS (RegExp on pathname) and handle(req, u, env, ctx).
// Add new endpoints inside your own module; do not edit this file.
import * as a from './kbx_a.js'; // home: live activity, search index, inline verification
import * as b from './kbx_b.js'; // AI desk review: live steps, quoted claims, red-team playground
import * as c from './kbx_c.js'; // buyer tools in the browser: PDF forensics, image match, IBAN
import * as d from './kbx_d.js'; // developer intelligence: domain age, promise drift, what-if score
import * as e from './kbx_e.js'; // data platform: SQL dataset, MCP server
import * as f from './kbx_f.js'; // reliability: web vitals, chaos drills, journeys, CSP
import * as g from './kbx_g.js'; // satellite: optical progress, on-demand plot, milestone payments
import * as h from './kbx_h.js'; // market truth: official prices, registers, risk patterns
import * as i from './kbx_i.js'; // two-sided: developer reply portal, encrypted deal room
import * as j from './kbx_j.js'; // reach: extension on portals, Telegram forward-check, push alerts
import * as k from './kbx_k.js'; // platform: SDKs, API keys and metering, Ask Kolaboro
import * as l from './kbx_l.js'; // trust: trust center, investor dossier, safe deploys
import * as m from './kbx_m.js'; // open: open-source verifiers, property tests, live report
import * as n from './kbx_n.js'; // provenance: number lineage, page integrity, reproducible builds
import * as o from './kbx_o.js'; // community trust: log witnesses, AI benchmark, bounty, SLOs
import * as p from './kbx_p.js'; // land: natural hazards, zoning
import * as q from './kbx_q.js'; // people: company graph, court records, mystery shopper
import * as r from './kbx_r.js'; // change: visual diffs, image authenticity, price index
import * as s from './kbx_s.js'; // private AI: in-browser contract reader, legal citations, permit QR
import * as t from './kbx_t.js'; // network: signed buyer reports, offline visit app, webhooks, Lighthouse CI
import * as u from './kbx_u.js'; // land and climate: climate scenarios, protected land, night lights, stalled sites
import * as v from './kbx_v.js'; // market statistics: delay index, on-time odds, monthly press release
import * as w from './kbx_w.js'; // registers: global company graph (GLEIF), insolvency watch, agent licence check
import * as x from './kbx_x.js'; // money tools: price below build cost, currency risk, late-handover compensation
import * as y from './kbx_y.js'; // AI follow-up: promise tracker, natural-language alerts, developer questions
import * as z from './kbx_z.js'; // evidence and partners: court-ready case file, Internet Archive copies, risk feed for banks and insurers
import * as m_ship from './kbx_ship.js'; // shipping: daily ship log, streak, engineering metrics, roadmap sync, feeds
import * as m_data from './kbx_data.js'; // open data platform: catalog, data contracts, freshness, OpenAPI explorer
import * as m_disc from './kbx_disc.js'; // discovery: world map, similar projects, market comparison, project timeline, display currency
import * as m_qa from './kbx_qa.js'; // quality engineering: visual regression, page weight, SBOM, real-user vitals, accessibility
import * as m_live from './kbx_live.js'; // status: server-side endpoint checks and incident history, CSP violation counts (b9c)
import * as m_ins from './kbx_ins.js'; // insight: weekly market digest, market page figures, score explainer, project-scoped questions, change heatmap
const MODS = [a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t, u, v, w, x, y, z, m_ship, m_data, m_disc, m_qa, m_ins, m_live];
export async function route(req, u, env, ctx) {
  for (const m of MODS) if (m.PATHS && m.PATHS.test(u.pathname)) return m.handle(req, u, env, ctx);
  return new Response(JSON.stringify({ error: 'not found' }), { status: 404, headers: { 'content-type': 'application/json' } });
}
